#!/usr/bin/env python3
"""Compute numeric ground truth for CSX-063_Q1."""

from __future__ import annotations

import html
import json
import re
from collections import Counter
from datetime import date
from pathlib import Path
from typing import Any


TASK_ID = "CSX-063_Q1"
PACKAGE_ID = "CSX-063"

TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = TASK_DIR.parents[2]
PACKAGE_ROOT = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / PACKAGE_ID
OUTPUT_PATH = TASK_DIR / "computed_gt.json"

EVENT_REL = "metadata/event.json"
REPORT_REL = "data/event_reports/event_reports_001_Locked_package_evidence_report.html"
ANCHOR_REL = "data/event_reports/event_reports_003_Locked_event_anchor_July_2021_Henan_Zhengzhou_extreme_rainfall_and_flood.json"
ERA5_REL = "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json"
GPM_REL = "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json"
CHIRPS_REL = "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json"
WORLDPOP_REL = "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json"
OSM_REL = "data/exposure_impact/exposure_impact_003_Overpass_small_roads_and_critical_amenities.json"


def read_json(rel_path: str) -> Any:
    return json.loads((PACKAGE_ROOT / rel_path).read_text(encoding="utf-8-sig"))


def read_report_text(rel_path: str) -> str:
    raw = (PACKAGE_ROOT / rel_path).read_text(encoding="utf-8", errors="replace")
    text = re.sub(r"<script.*?</script>", " ", raw, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<style.*?</style>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def first_float(pattern: str, text: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1).replace(",", ""))


def first_int(pattern: str, text: str) -> int:
    return int(first_float(pattern, text))


def round_float(value: float, digits: int = 3) -> float:
    return round(float(value), digits)


def inclusive_days(start: str, end: str) -> int:
    start_date = date.fromisoformat(start)
    end_date = date.fromisoformat(end)
    return (end_date - start_date).days + 1


def osm_counts() -> dict[str, int]:
    data = read_json(OSM_REL)
    highway_counts: Counter[str] = Counter()
    amenity_counts: Counter[str] = Counter()
    tunnel_yes = 0

    for elem in data.get("elements", []):
        tags = elem.get("tags") or {}
        if "highway" in tags:
            highway_counts[tags["highway"]] += 1
        if "amenity" in tags:
            amenity_counts[tags["amenity"]] += 1
        if tags.get("tunnel") == "yes":
            tunnel_yes += 1

    return {
        "amenity_features": sum(amenity_counts.values()),
        "highway_features": sum(highway_counts.values()),
        "tunnel_features": tunnel_yes,
    }


def main() -> None:
    event = read_json(EVENT_REL)
    anchor = read_json(ANCHOR_REL)
    report = read_report_text(REPORT_REL)
    era5 = read_json(ERA5_REL)
    gpm = read_json(GPM_REL)
    chirps = read_json(CHIRPS_REL)
    worldpop = read_json(WORLDPOP_REL)
    osm = osm_counts()

    start = anchor["temporal_window"]["start_date"]
    end = anchor["temporal_window"]["end_date"]
    three_day_mm = first_float(r"total precipitation of\s+([0-9.]+)\s+mm", report)
    annual_mm = first_float(r"average annual precipitation of\s+([0-9.]+)\s+mm", report)
    one_hour_mm = first_float(r"registered\s+([0-9.]+)\s+mm of precipitation from 4 pm to 5 pm", report)
    trains_suspended_over = first_int(r"more than\s+([0-9,]+)\s+trains", report)

    hour_share = round_float(one_hour_mm / three_day_mm, 4)
    annual_ratio = round_float(three_day_mm / annual_mm, 3)

    gridded = {
        "era5_land": {
            "dataset": era5["dataset"],
            "mean_mm": round_float(era5["stats"]["precipitation_sum_mm_mean"]),
            "max_mm": round_float(era5["stats"]["precipitation_sum_mm_max"]),
            "min_mm": round_float(era5["stats"]["precipitation_sum_mm_min"]),
        },
        "gpm_imerg": {
            "dataset": gpm["dataset"],
            "mean_mm": round_float(gpm["stats"]["gpm_event_precip_mm_mean"]),
            "max_mm": round_float(gpm["stats"]["gpm_event_precip_mm_max"]),
            "min_mm": round_float(gpm["stats"]["gpm_event_precip_mm_min"]),
        },
        "chirps": {
            "dataset": chirps["dataset"],
            "mean_mm": round_float(chirps["stats"]["chirps_event_precip_mm_mean"]),
            "max_mm": round_float(chirps["stats"]["chirps_event_precip_mm_max"]),
            "min_mm": round_float(chirps["stats"]["chirps_event_precip_mm_min"]),
        },
    }
    mean_order = [
        name
        for name, _ in sorted(
            ((name, values["mean_mm"]) for name, values in gridded.items()),
            key=lambda item: item[1],
            reverse=True,
        )
    ]
    max_mean_dataset = mean_order[0]
    max_mean_mm = gridded[max_mean_dataset]["mean_mm"]
    max_grid_mm = max(values["max_mm"] for values in gridded.values())

    population_million = round_float(worldpop["population_sum"]["population"] / 1_000_000, 2)
    threshold_flags = {
        "annual_ratio_ge_0_90": annual_ratio >= 0.90,
        "highway_features_ge_200": osm["highway_features"] >= 200,
        "hour_share_ge_0_30": hour_share >= 0.30,
        "population_ge_5m": population_million >= 5.0,
    }
    final_label = (
        "short_burst_multiday_urban_exposure"
        if all(threshold_flags.values())
        else "mixed_or_incomplete_threshold_support"
    )

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": PACKAGE_ID,
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "target_family": "numeric_diagnosis",
        "difficulty_level": "L3",
        "event": {
            "event_id": event["package_id"],
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "hazard_label": event["hazard_label"],
            "region": event["region"],
            "temporal_window": {"start": start, "end": end, "days": inclusive_days(start, end)},
        },
        "primary_gt": {
            "answer": final_label,
            "metrics": {
                "annual_ratio": annual_ratio,
                "highway_features": osm["highway_features"],
                "hour_share": hour_share,
                "max_mean_mm": max_mean_mm,
                "max_mean_dataset": max_mean_dataset,
                "one_hour_mm": one_hour_mm,
                "population_million": population_million,
                "three_day_mm": three_day_mm,
            },
            "thresholds": {
                "annual_ratio_min": 0.90,
                "highway_features_min": 200,
                "hour_share_min": 0.30,
                "population_million_min": 5.0,
            },
            "tolerances": {
                "grid_mm": 0.5,
                "population_million": 0.05,
                "rain_mm": 0.2,
                "ratio": 0.005,
            },
        },
        "numeric_tolerances": {
            "annual_ratio": {"expected": annual_ratio, "abs_tolerance": 0.005},
            "highway_features": {"expected": osm["highway_features"], "abs_tolerance": 0},
            "hour_share": {"expected": hour_share, "abs_tolerance": 0.005},
            "max_grid_mm": {"expected": round_float(max_grid_mm), "abs_tolerance": 0.5},
            "max_mean_mm": {"expected": max_mean_mm, "abs_tolerance": 0.5},
            "one_hour_mm": {"expected": one_hour_mm, "abs_tolerance": 0.2},
            "population_million": {"expected": population_million, "abs_tolerance": 0.05},
            "three_day_mm": {"expected": three_day_mm, "abs_tolerance": 0.2},
        },
        "key_values": {
            "event_window": {"start": start, "end": end, "days": inclusive_days(start, end)},
            "reported_rainfall": {
                "annual_average_mm": annual_mm,
                "annual_ratio": annual_ratio,
                "hour_share": hour_share,
                "one_hour_mm": one_hour_mm,
                "three_day_mm": three_day_mm,
                "trains_suspended_over": trains_suspended_over,
            },
            "gridded_accumulation": {
                "by_dataset": gridded,
                "gpm_mean_to_chirps_mean_ratio": round_float(
                    gridded["gpm_imerg"]["mean_mm"] / gridded["chirps"]["mean_mm"], 4
                ),
                "gpm_mean_to_era5_mean_ratio": round_float(
                    gridded["gpm_imerg"]["mean_mm"] / gridded["era5_land"]["mean_mm"], 4
                ),
                "max_grid_mm": round_float(max_grid_mm),
                "max_mean_mm": max_mean_mm,
                "max_mean_dataset": max_mean_dataset,
                "mean_order": mean_order,
            },
            "exposure_context": {
                "amenity_features": osm["amenity_features"],
                "highway_features": osm["highway_features"],
                "population_million": population_million,
                "population_sum": round_float(worldpop["population_sum"]["population"]),
                "tunnel_features": osm["tunnel_features"],
            },
            "threshold_flags": threshold_flags,
            "final_label": final_label,
            "formulas": {
                "annual_ratio": "three_day_mm / annual_average_mm",
                "hour_share": "one_hour_mm / three_day_mm",
                "max_grid_mm": "max(dataset max_mm values)",
                "max_mean_dataset": "dataset with largest event-window mean_mm",
            },
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "output_schema",
                    "points": 2,
                    "description": "Returns the requested compact JSON fields with units clear in field names and one concise interpretation sentence.",
                    "partial_credit": "1 point if the answer has the final label and most numeric fields but omits or misnests one ledger block.",
                },
                {
                    "name": "reported_rainfall_arithmetic",
                    "points": 4,
                    "description": "Gives 617.1 mm, 201.9 mm, 201.9 / 617.1 = 0.3272, and 617.1 / 640.8 = 0.963 within tolerance.",
                    "partial_credit": "2-3 points for correct rainfall anchors with one missing or rounded ratio; 1 point for only copying one or two rainfall values.",
                },
                {
                    "name": "gridded_accumulation_ledger",
                    "points": 4,
                    "description": "Orders mean accumulation as GPM IMERG, CHIRPS, ERA5-Land; gives 460.551 mm for the top mean and 484.255 mm for the gridded maximum within tolerance.",
                    "partial_credit": "2-3 points for the right top dataset with one numeric error; 1 point for recognizing GPM IMERG is largest without the ledger values.",
                },
                {
                    "name": "urban_context_ledger",
                    "points": 3,
                    "description": "Gives 5.26 million people, 252 highway features, 48 amenity features, and 0 tunnel features within tolerance.",
                    "partial_credit": "2 points for correct population and highway count with minor omissions; 1 point for only the population value.",
                },
                {
                    "name": "threshold_logic_and_final_label",
                    "points": 5,
                    "description": "Correctly evaluates all four Boolean checks and assigns short_burst_multiday_urban_exposure only when all are true.",
                    "partial_credit": "3-4 points for the correct label with one threshold mistake; 1-2 points for correct individual checks but an incorrect or missing final label.",
                },
                {
                    "name": "computed_interpretation",
                    "points": 2,
                    "description": "Ties the one-hour share, near-annual multi-day total, gridded rainfall, and urban context into a concise computed interpretation.",
                    "partial_credit": "1 point if the interpretation mentions only the rainfall thresholds or only the urban context.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                EVENT_REL,
                REPORT_REL,
                ANCHOR_REL,
                ERA5_REL,
                GPM_REL,
                CHIRPS_REL,
                WORLDPOP_REL,
                OSM_REL,
            ],
            "notes": "Computed from local CSX-063 records and data layers.",
        },
    }

    OUTPUT_PATH.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
